const updateMetadata = `-- name: UpdateMetadata :exec
UPDATE documents.documents SET title = $1, code = $2, doc_type = $3, status = $4,
  department = $5, owner_id = $6, approved_at = $7, review_due_at = $8,
  language = $9, attributes = $10, updated_at = now()
WHERE id = $11
`

type UpdateMetadataParams struct {
	Title       string
	Code        string
	DocType     string
	Status      string
	Department  string
	OwnerID     *uuid.UUID
	ApprovedAt  *time.Time
	ReviewDueAt *time.Time
	Language    string
	Attributes  []byte
	ID          uuid.UUID
}

func (q *Queries) UpdateMetadata(ctx context.Context, arg UpdateMetadataParams) error {
	_, err := q.db.Exec(ctx, updateMetadata,
		arg.Title,
		arg.Code,
		arg.DocType,
		arg.Status,
		arg.Department,
		arg.OwnerID,
		arg.ApprovedAt,
		arg.ReviewDueAt,
		arg.Language,
		arg.Attributes,
		arg.ID,
	)
	return err
}

const upsertDocument = `-- name: UpsertDocument :one
INSERT INTO documents.documents (source_id, external_id, title, acl_set_id)
VALUES ($1, $2, $3, $4)
ON CONFLICT (source_id, external_id) DO UPDATE SET deleted_at = NULL, updated_at = now()
RETURNING id
`

type UpsertDocumentParams struct {
	SourceID   uuid.UUID
	ExternalID string
	Title      string
	AclSetID   *uuid.UUID
}

func (q *Queries) UpsertDocument(ctx context.Context, arg UpsertDocumentParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertDocument,
		arg.SourceID,
		arg.ExternalID,
		arg.Title,
		arg.AclSetID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertVersion = `-- name: UpsertVersion :one
INSERT INTO documents.document_versions (document_id, content_hash, mime, size)
VALUES ($1, $2, $3, $4)
ON CONFLICT (document_id, content_hash) DO UPDATE SET state = 'processing'
RETURNING id
`

type UpsertVersionParams struct {
	DocumentID  uuid.UUID
	ContentHash string
	Mime        string
	Size        int64
}

// Content seen before (a revert) reuses its version; derived artifacts are cached, so reprocessing is cheap.
func (q *Queries) UpsertVersion(ctx context.Context, arg UpsertVersionParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertVersion,
		arg.DocumentID,
		arg.ContentHash,
		arg.Mime,
		arg.Size,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
